/**
 * Article ref minting per ADR-0004.
 *
 * An article has exactly one public identity: art-<yyyymmdd>-<hex8>, minted
 * once by Feed at first acquisition. It carries no publisher, title, or URL
 * semantics: the date segment is only the UTC calendar date of the
 * acquisition timestamp (extracted_at), and the hex segment is 8 random
 * lowercase hex characters. Only Feed mints refs; this module is the only
 * place that does.
 */

import { randomBytes } from 'crypto';

const ARTICLE_REF_PATTERN = /^art-\d{8}-[0-9a-f]{8}$/;

/** Mint a new opaque article ref. `extractedAtIso` should be the article's own extracted_at. */
export function mintArticleRef(extractedAtIso: string): string {
  const parsed = new Date(extractedAtIso);
  const dateForRef = Number.isNaN(parsed.getTime()) ? new Date() : parsed;
  const yyyymmdd = dateForRef.toISOString().slice(0, 10).replace(/-/g, '');
  const hex8 = randomBytes(4).toString('hex');
  return `art-${yyyymmdd}-${hex8}`;
}

/** True if the value has the shape of an ADR-0004 article ref (not a DB existence check). */
export function isArticleRef(value: string): boolean {
  return ARTICLE_REF_PATTERN.test(value);
}

